@Component("transferOrder-handler")
@ProcessingGroup("transferOrder-processing-group")
public class TransferOrderEventHandler {
	
	// core constructor
	TransferOrderEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateTransferOrderEvent
     */
    @EventHandler
    public void handle( CreateTransferOrderEvent event) {
        entityManager.persist(new TransferOrder(event.getTransferOrderId(), event.getOrderNumber(), event.getRequestedShipDate(), event.getRequestedReceiveDate(), event.getShippedDate(), event.getReceivedDate(), event.getOriginWarehouse(), event.getDestinationWarehouse(), event.getLines(), event.getTransactions(), event.getStatus()));
    }

    /*
     * @param	event UpdateTransferOrderEvent
     */
    @EventHandler
    public TransferOrder handle( UpdateTransferOrderEvent event) {
    	entityManager.merge(new TransferOrder(event.getTransferOrderId(), event.getOrderNumber(), event.getRequestedShipDate(), event.getRequestedReceiveDate(), event.getShippedDate(), event.getReceivedDate(), event.getOriginWarehouse(), event.getDestinationWarehouse(), event.getLines(), event.getTransactions(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteTransferOrderEvent
     */
    @EventHandler
    public void on( DeleteTransferOrderEvent event) {
    	TransferOrder entity = new TransferOrder();
   
    	// ------------------------------------------
    	// apply the TransferOrderId
    	// ------------------------------------------
    	entity.setTransferOrderId( event.getTransferOrderId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final TransferOrderRepository transferOrderEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(TransferOrderEventHandler.class.getName());

}
